"""MPS paged-KV cache write.

Routes through the native Metal kernel
``_native.ops.reshape_and_cache_flash_into`` (one dispatch
per call) when shapes/dtypes are supported. Falls back to a Python
loop scatter for shapes the kernel doesn't cover.

Why we used to live in the Python loop: the shared
``reshape_and_cache_flash_torch`` fallback uses advanced-index
assignment patterns (``cache[blocks, offsets, :, :]``) that go
through MPS dispatch paths that don't interact well with PyTorch's
bf16 casts in the write code. The Metal kernel sidesteps the
indexing-pattern problem entirely (one explicit scatter per token)
and folds N dispatches into one.

Callers that read back from the cache shortly after this returns may
need to force materialization (e.g. via ``.to("cpu")`` or
``torch.mps.synchronize()``) — MPS keeps writes queued, and a
``cache[int, int]`` read doesn't always see pending writes until the
command queue drains. The ``tests/mps/test_cache.py`` fixtures
demonstrate the pattern.

FP8 KV uses uint8 views over ``torch.float8_e4m3fn`` cache storage; MPS
can allocate float8 buffers but PyTorch cannot convert to/from float8
on device, so quantization stays in the Metal scatter kernel.
"""

import torch

# Side-effect import: loads the sidecar bridge, the pre-built Metal
# library, and exposes the direct native op surface.
from kestrel_kernels.mps import _native
from kestrel_kernels.paged_kv_metadata_ops.fallback import (
    build_paged_kv_metadata_torch,
)


# Dtypes the Metal kernel ships source/cache specializations for.
_NATIVE_DTYPES = (torch.float16, torch.float32)
_FP8_KV_DTYPES = {"fp8", "fp8_e4m3"}


def _is_float8_e4m3(tensor: torch.Tensor) -> bool:
    return hasattr(torch, "float8_e4m3fn") and tensor.dtype == torch.float8_e4m3fn


def _as_float32_scale_tensor(scale: torch.Tensor | float, device: torch.device) -> torch.Tensor:
    if isinstance(scale, torch.Tensor):
        if (
            scale.device == device
            and scale.dtype == torch.float32
            and scale.is_contiguous()
            and scale.numel() == 1
        ):
            return scale.reshape(())
        return scale.to(device=device, dtype=torch.float32).reshape(()).contiguous()
    value = float(scale)
    if value <= 0.0:
        raise ValueError("FP8 KV cache scales must be positive")
    return torch.tensor(value, device=device, dtype=torch.float32)


def reshape_and_cache_flash_mps(
    key: torch.Tensor,
    value: torch.Tensor,
    key_cache: torch.Tensor,
    value_cache: torch.Tensor,
    slot_mapping: torch.Tensor,
    kv_cache_dtype: str,
    k_scale: torch.Tensor,
    v_scale: torch.Tensor,
) -> None:
    """Scatter ``key``/``value`` into paged KV caches indexed by ``slot_mapping``."""
    is_fp8 = kv_cache_dtype in _FP8_KV_DTYPES
    if not is_fp8 and kv_cache_dtype != "auto":
        raise NotImplementedError(
            f"kestrel-kernels MPS backend: kv_cache_dtype={kv_cache_dtype!r} "
            "is not supported; expected 'auto' or 'fp8_e4m3'."
        )
    n_slots = int(slot_mapping.numel())
    # Match the shared fallback's fail-fast behavior — silently
    # dropping trailing tokens on a length mismatch corrupts the cache
    # unobservably.
    if n_slots != int(key.shape[0]) or n_slots != int(value.shape[0]):
        raise ValueError(
            f"slot_mapping and key/value token dimensions must match "
            f"(slots={n_slots}, key={int(key.shape[0])}, "
            f"value={int(value.shape[0])})"
        )
    if n_slots == 0:
        return

    # Native Metal scatter. The kernel-side ``TORCH_CHECK``s in
    # ``mps_ops.mm`` validate the contract; the predicate here is a
    # cheap pre-filter that lets unsupported shapes skip to the
    # fallback rather than raise. ``key/value`` get cast to the cache
    # dtype (no-op when already-matching, which is the production
    # callsite) + made contiguous so the kernel can index linearly.
    fp8_cache_dtype_ok = is_fp8 and (
        key_cache.dtype == torch.uint8
        or _is_float8_e4m3(key_cache)
    ) and (
        value_cache.dtype == torch.uint8
        or _is_float8_e4m3(value_cache)
    )
    auto_cache_dtype_ok = (
        not is_fp8
        and key_cache.dtype in _NATIVE_DTYPES
        and key_cache.dtype == value_cache.dtype
    )
    if (
        (auto_cache_dtype_ok or fp8_cache_dtype_ok)
        and key.dim() == 3
        and value.dim() == 3
        and key_cache.dim() == 4
        and value_cache.dim() == 4
        and key_cache.is_contiguous()
        and value_cache.is_contiguous()
    ):
        if is_fp8:
            key_src = key if key.dtype in _NATIVE_DTYPES else key.to(dtype=torch.float16)
            value_src = (
                value if value.dtype in _NATIVE_DTYPES else value.to(dtype=torch.float16)
            )
            key_cache_native = (
                key_cache if key_cache.dtype == torch.uint8 else key_cache.view(torch.uint8)
            )
            value_cache_native = (
                value_cache
                if value_cache.dtype == torch.uint8
                else value_cache.view(torch.uint8)
            )
            k_scale_native = _as_float32_scale_tensor(k_scale, key.device)
            v_scale_native = _as_float32_scale_tensor(v_scale, key.device)
        else:
            key_src = key.to(dtype=key_cache.dtype)
            value_src = value.to(dtype=value_cache.dtype)
            key_cache_native = key_cache
            value_cache_native = value_cache
            k_scale_native = None
            v_scale_native = None
        key_src = key_src.contiguous()
        value_src = value_src.contiguous()
        # Normalize ``slot_mapping`` to MPS-int64-1D-contiguous. The
        # prior ``.tolist()`` loop tolerated a CPU ``slot_mapping``
        # (host transfer happened implicitly); the native op enforces
        # same-device on every tensor, so we move it to ``key.device``
        # if needed. Skipping this would make the kernel-side
        # ``TORCH_CHECK`` fail on a CPU slot_mapping that the old path
        # accepted.
        slots_native = slot_mapping
        if (
            slots_native.device != key.device
            or slots_native.dtype != torch.int64
            or not slots_native.is_contiguous()
            or slots_native.dim() != 1
        ):
            slots_native = (
                slots_native.to(device=key.device, dtype=torch.int64)
                .reshape(-1)
                .contiguous()
            )
        _native.ops.reshape_and_cache_flash_into(
            key_src,
            value_src,
            key_cache_native,
            value_cache_native,
            slots_native,
            k_scale_native,
            v_scale_native,
            is_fp8,
        )
        return

    if is_fp8:
        raise NotImplementedError(
            "kestrel-kernels MPS backend: FP8 KV cache write requires 3-D "
            "key/value and contiguous 4-D uint8/float8 cache buffers."
        )

    # Fallback: per-token slice assignment in a Python loop. Slow
    # (one dispatch per token), but reproduces the previous behavior
    # for any shape/dtype the kernel doesn't cover.
    block_size = int(key_cache.shape[1])
    key_src = key.to(dtype=key_cache.dtype)
    value_src = value.to(dtype=value_cache.dtype)
    slots_list = slot_mapping.contiguous().view(-1).to(torch.int64).tolist()
    for i, slot in enumerate(slots_list):
        # Negative slots (commonly ``-1``) mark padded tokens — skip
        # them, matching the CUDA reference semantics. Python's
        # negative indexing would otherwise corrupt the last page.
        if slot < 0:
            continue
        p = slot // block_size
        o = slot - p * block_size
        key_cache[p, o] = key_src[i]
        value_cache[p, o] = value_src[i]


def build_paged_kv_metadata_mps(
    page_table: torch.Tensor,
    batch_idx: torch.Tensor,
    input_pos: torch.Tensor,
    out_page_table: torch.Tensor,
    out_seqused_k: torch.Tensor,
    page_size: int,
) -> None:
    """Build compact paged-KV metadata on MPS with one Metal dispatch."""
    batch_size = int(batch_idx.shape[0])
    if batch_size == 0:
        return

    if (
        _native.ops is not None
        and hasattr(_native.ops, "build_paged_kv_metadata_into")
        and page_table.device.type == "mps"
        and page_table.device == out_page_table.device
        and page_table.device == out_seqused_k.device
        and page_table.dtype == torch.int32
        and input_pos.dtype == torch.int32
        and out_page_table.dtype == torch.int32
        and out_seqused_k.dtype == torch.int32
        and page_table.ndim == 2
        and batch_idx.ndim == 1
        and input_pos.ndim == 1
        and out_page_table.ndim == 2
        and out_seqused_k.ndim == 1
        and int(input_pos.shape[0]) == batch_size
        and int(out_page_table.shape[0]) >= batch_size
        and int(out_page_table.shape[1]) >= int(page_table.shape[1])
        and int(out_seqused_k.shape[0]) >= batch_size
        and page_table.is_contiguous()
        and out_page_table.is_contiguous()
        and out_seqused_k.is_contiguous()
    ):
        batch_idx_native = batch_idx
        if (
            batch_idx_native.device != page_table.device
            or batch_idx_native.dtype != torch.int64
            or not batch_idx_native.is_contiguous()
        ):
            batch_idx_native = batch_idx_native.to(
                device=page_table.device, dtype=torch.int64
            ).contiguous()
        input_pos_native = input_pos
        if (
            input_pos_native.device != page_table.device
            or not input_pos_native.is_contiguous()
        ):
            input_pos_native = input_pos_native.to(
                device=page_table.device, dtype=torch.int32
            ).contiguous()
        _native.ops.build_paged_kv_metadata_into(
            page_table,
            batch_idx_native,
            input_pos_native,
            out_page_table,
            out_seqused_k,
            int(page_size),
        )
        return

    build_paged_kv_metadata_torch(
        page_table,
        batch_idx,
        input_pos,
        out_page_table,
        out_seqused_k,
        page_size,
    )


__all__ = ["reshape_and_cache_flash_mps", "build_paged_kv_metadata_mps"]
